// KumirLexerInit initializes any static state used to implement KumirLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewKumirLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func KumirLexerInit() {
	staticData := &KumirLexerLexerStaticData
	staticData.once.Do(kumirlexerLexerInit)
}

// NewKumirLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewKumirLexer(input antlr.CharStream) *KumirLexer {
	KumirLexerInit()
	l := new(KumirLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &KumirLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "KumirLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

